from runtime_sdk import NodeContext


def run(ctx: NodeContext):
    """错误处理：捕获上游异常并给出兜底动作。"""
    err = ctx.state.get("last_error")
    if not err:
        return ctx.text
    ctx.log(f"捕获错误：{err}")
    return ctx.llm(
        f"执行出错：{err}\n原始输入：{ctx.text}\n请给出修复步骤或替代方案。",
        system="你是故障排查专家。",
    )

